-- Per-distance gain / cut-off / blurb are the columns added in 20260806090000.
-- The event-level figures stay the headline; these are what a runner actually
-- decides on once a 100K and a 10K sit on the same page.
--
-- The ROAD event leaves cut-off null on purpose — fun runs rarely publish one,
-- and the site omits any fact it has no value for rather than printing a zero.
-- Its 10K also ships with slots_taken high enough to show the scarcity state
-- without inventing it.
insert into categories (
  id, org_id, event_id, code, label, distance_km, base_price, slots_total, slots_taken,
  elevation_gain_m, cutoff_hours, blurb
) values
  -- Dahilayan Sky Ultra (trail)
  ('00000000-0000-0000-0000-0000000000c1','00000000-0000-0000-0000-0000000000a1','00000000-0000-0000-0000-0000000000e3','60K','60K Ultra',60,320000,120,18,
   1223, 14.0, 'The full Kitanglad loop. Qualifier required.'),
  ('00000000-0000-0000-0000-0000000000c2','00000000-0000-0000-0000-0000000000a1','00000000-0000-0000-0000-0000000000e3','30K','30K',30,220000,180,44,
   700, 9.0, 'Pine ridge and cloud forest, turning back below the saddle.'),
  ('00000000-0000-0000-0000-0000000000c3','00000000-0000-0000-0000-0000000000a1','00000000-0000-0000-0000-0000000000e3','15K','15K',15,140000,220,203,
